import {CategoryType} from "./category";

export enum CatalogGenerationJobStatus {
    Pending = 0,
    Running = 1,
    Completed = 2,
    Failed = 3,
    Cancelled = 4,
}

export enum CatalogGenerationPriceMode {
    Single = 0,
    ByModification = 1,
}

export interface GenerationModificationValue {
    value: string;
    price: string;
}

export interface GenerationModification {
    name: string;
    values: GenerationModificationValue[];
    addToName: boolean;
    addToDescription: boolean;
    affectsPrice: boolean;
}

export interface GenerationPricing {
    modificationNames: string[];
    combinationPrices: Array<{
        values: Record<string, string>;
        price: number;
    }>;
}

export interface GenerationAvailabilityMatrix {
    unavailableCombinationKeys: string[];
}

export interface CatalogGenerationForm {
    batchName: string;
    name: string;
    description: string;
    price: string;
    categoryId: string;
    itemType: CategoryType;
    initialStockQuantity: string;
    priceMode: CatalogGenerationPriceMode;
}

export interface StartCatalogGenerationResult {
    jobId: string;
    total: number;
    batchId: string;
}

export interface CatalogGenerationJob {
    id: string;
    status: CatalogGenerationJobStatus;
    total: number;
    processed: number;
    created: number;
    failed: number;
    error?: string | null;
    createdAt: string;
    startedAt?: string | null;
    completedAt?: string | null;
}

export interface CatalogGenerationBatch {
    id: string;
    name: string;
    baseItemName: string;
    itemType: CategoryType;
    status: CatalogGenerationJobStatus;
    total: number;
    created: number;
    failed: number;
    createdAt: string;
    completedAt?: string | null;
    revision: number;
}

export interface GenerationBatchDraftModification {
    name: string;
    values: string[];
    addToName: boolean;
    addToDescription: boolean;
    valuePrices: Array<{value: string; price: number}>;
}

export interface CatalogGenerationBatchDraft {
    batchId: string;
    batchName: string;
    name: string;
    description: string;
    price: number;
    priceMode: CatalogGenerationPriceMode;
    priceModificationName?: string | null;
    pricing?: GenerationPricing | null;
    categoryId: number;
    itemType: CategoryType;
    initialStockQuantity: number;
    imageUrl: string;
    modifications: GenerationBatchDraftModification[];
    fields: Record<string, string>;
    availabilityMatrix?: {
        unavailableCombinations: Array<{values: Record<string, string>}>;
    } | null;
    revision: number;
}

export interface DeleteCatalogGenerationBatchResult {
    deletedProducts: number;
    deletedServices: number;
}
