import React, {useEffect, useMemo, useRef, useState} from "react";
import {Checkbox, FormControlLabel, IconButton, InputLabel, LinearProgress, Pagination, Typography} from "@mui/material";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import ViewListOutlinedIcon from "@mui/icons-material/ViewListOutlined";
import RestartAltOutlinedIcon from "@mui/icons-material/RestartAltOutlined";
import styledCom from "styled-components";
import {toast} from "react-toastify";
import {NavLink, useSearchParams} from "react-router-dom";
import {CategoryType} from "../../models/category";
import {
    CatalogGenerationForm,
    CatalogGenerationJobStatus,
    CatalogGenerationPriceMode,
    GenerationAvailabilityMatrix,
    GenerationModification,
} from "../../models/catalogGeneration";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import {
    useCancelCatalogGenerationMutation,
    useEditCatalogGenerationBatchMutation,
    useGetCatalogGenerationStatusQuery,
    useGetCatalogGenerationBatchDraftQuery,
    useStartCatalogGenerationMutation,
} from "./catalogGenerationApi";
import {useTranslation} from "../../i18n";
import {getApiErrorMessage} from "../../api/errors";
import {useAppDispatch} from "../../store/store";
import {productsApi} from "../products/productsApi";
import {servicesApi} from "../services/servicesApi";
import {stockApi} from "../stock/stockApi";
import {FormSurface, MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, Surface} from "../../ui/commonStyled/commonStyled";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import CoreTextField from "../../ui/textFields/coreTextField";
import CoreButton from "../../ui/buttons/coreButton";
import ImageUploadField from "../../ui/fileUpload/ImageUploadField";
import CustomFieldEditor, {
    CustomFieldRow,
    customFieldRowsToRecord,
    customFieldsToRows,
    getCustomFieldsValidationError,
} from "../shared/customFields/CustomFieldEditor";
import CatalogGenerationTabs from "./CatalogGenerationTabs";

const ModificationCard = styledCom.section({display: "grid", gap: "10px", padding: "14px", border: "1px solid var(--color-border)", borderRadius: "12px"});
const ModificationHeader = styledCom.div({display: "grid", gridTemplateColumns: "minmax(0, 1fr) auto", gap: "10px", alignItems: "center"});
const ValueRow = styledCom.div({display: "grid", gridTemplateColumns: "minmax(0, 1fr) auto", gap: "10px", alignItems: "center", marginLeft: "18px"});
const ValueFields = styledCom.div({display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "10px", alignItems: "center"});
const ModificationOptions = styledCom.div({display: "flex", flexWrap: "wrap", gap: "6px 18px", marginLeft: "18px"});
const AvailabilityPanel = styledCom.section({display: "grid", gap: "12px", padding: "14px", border: "1px solid var(--color-border)", borderRadius: "12px"});
const MatrixScroller = styledCom.div({maxWidth: "100%", overflowX: "auto"});
const MatrixTable = styledCom.table({borderCollapse: "collapse", minWidth: "100%"});
const MatrixHeaderCell = styledCom.th({padding: "8px 12px", border: "1px solid var(--color-border)", textAlign: "center", whiteSpace: "nowrap"});
const MatrixCell = styledCom.td({padding: "4px 10px", border: "1px solid var(--color-border)", textAlign: "center"});
const MatrixPagination = styledCom.div({display: "flex", justifyContent: "center", paddingTop: "4px"});
const PriceToolbar = styledCom.div({display: "grid", gridTemplateColumns: "minmax(180px, 1fr) auto", gap: "10px", alignItems: "center"});
const PricingFilters = styledCom.div({display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: "10px", alignItems: "center"});
const PriceCellContent = styledCom.div({display: "grid", gridTemplateColumns: "minmax(150px, 1fr) auto", gap: "6px", alignItems: "center", minWidth: "210px"});
const PriceOrigin = styledCom.small<{changed: boolean}>(({changed}) => ({gridColumn: "1 / -1", color: changed ? "var(--color-primary)" : "var(--color-muted)", textAlign: "left", fontWeight: changed ? 700 : 500}));
const Summary = styledCom.div({display: "grid", gap: "8px", padding: "14px", borderRadius: "12px", background: "var(--color-primary-soft)", border: "1px solid var(--color-primary-border)"});
const ErrorText = styledCom.p({margin: 0, color: "var(--color-danger)", fontWeight: 650});
const JobPanel = styledCom(Surface)({display: "grid", gap: "12px", marginTop: "18px"});
const availabilityPageSize = 50;
const pricingPageSize = 50;
const maximumPreviewCombinations = 10000;

const normalizeAvailabilityValue = (value: string) => value.trim().toLocaleLowerCase();

const getCombinationValues = (modifications: GenerationModification[], index: number) => {
    const result = new Array<string>(modifications.length);
    let remainder = index;
    for (let dimension = modifications.length - 1; dimension >= 0; dimension--) {
        const values = modifications[dimension].values;
        const valueIndex = remainder % values.length;
        remainder = Math.floor(remainder / values.length);
        result[dimension] = values[valueIndex].value;
    }
    return result;
};

const createAvailabilityKey = (values: string[]) => JSON.stringify(values.map(normalizeAvailabilityValue));
const createPricingKey = (names: string[], values: string[]) => JSON.stringify(
    names.map((name, index) => [normalizeAvailabilityValue(name), normalizeAvailabilityValue(values[index] ?? "")]),
);

const initialForm: CatalogGenerationForm = {
    batchName: "",
    name: "",
    description: "",
    price: "",
    categoryId: "",
    itemType: CategoryType.Product,
    initialStockQuantity: "0",
    priceMode: CatalogGenerationPriceMode.Single,
};

const CatalogGenerationPage = () => {
    const {t} = useTranslation();
    const dispatch = useAppDispatch();
    const [searchParams] = useSearchParams();
    const editBatchId = searchParams.get("editBatchId") || "";
    const isEditMode = Boolean(editBatchId);
    const hydratedBatchId = useRef("");
    const [form, setForm] = useState(initialForm);
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [existingImageUrl, setExistingImageUrl] = useState("");
    const [modifications, setModifications] = useState<GenerationModification[]>([
        {name: "", values: [{value: "", price: ""}], addToName: false, addToDescription: false, affectsPrice: false},
    ]);
    const [fields, setFields] = useState<CustomFieldRow[]>([]);
    const [fieldsError, setFieldsError] = useState("");
    const [combinationPrices, setCombinationPrices] = useState<Record<string, string>>({});
    const [fillPrice, setFillPrice] = useState("");
    const [pricingFilters, setPricingFilters] = useState<Record<number, string>>({});
    const [pricingPage, setPricingPage] = useState(1);
    const [availabilityMatrix, setAvailabilityMatrix] = useState<GenerationAvailabilityMatrix | null>(null);
    const [availabilityPage, setAvailabilityPage] = useState(1);
    const [validationError, setValidationError] = useState("");
    const [jobId, setJobId] = useState<string>();
    const {data: batchDraft} = useGetCatalogGenerationBatchDraftQuery(
        editBatchId,
        {skip: !editBatchId},
    );
    const {data: categories = []} = useGetLastLevelCategoriesQuery({type: form.itemType});
    const [startGeneration, {isLoading: isStarting}] = useStartCatalogGenerationMutation();
    const [editGenerationBatch, {isLoading: isEditing}] = useEditCatalogGenerationBatchMutation();
    const isSaving = isStarting || isEditing;
    const [cancelGeneration, {isLoading: isCancelling}] = useCancelCatalogGenerationMutation();
    const statusQuery = useGetCatalogGenerationStatusQuery(jobId!, {skip: !jobId});
    const job = statusQuery.data;
    const isTerminal = job?.status === CatalogGenerationJobStatus.Completed ||
        job?.status === CatalogGenerationJobStatus.Failed ||
        job?.status === CatalogGenerationJobStatus.Cancelled;

    useEffect(() => {
        if (!batchDraft || hydratedBatchId.current === batchDraft.batchId) return;
        hydratedBatchId.current = batchDraft.batchId;
        const pricingNames = batchDraft.pricing?.modificationNames ??
            (batchDraft.priceModificationName ? [batchDraft.priceModificationName] : []);
        const draftModifications: GenerationModification[] = batchDraft.modifications.map((modification) => ({
            name: modification.name,
            addToName: modification.addToName,
            addToDescription: modification.addToDescription,
            affectsPrice: pricingNames.some((name) =>
                name.toLocaleLowerCase() === modification.name.toLocaleLowerCase()),
            values: modification.values.map((value) => ({
                value,
                price: "",
            })),
        }));
        const pricingRows = batchDraft.pricing?.combinationPrices ??
            (batchDraft.priceModificationName
                ? batchDraft.modifications
                    .find((modification) => modification.name.toLocaleLowerCase() ===
                        batchDraft.priceModificationName?.toLocaleLowerCase())
                    ?.valuePrices.map((item) => ({
                        values: {[batchDraft.priceModificationName!]: item.value},
                        price: item.price,
                    })) ?? []
                : []);
        const formPricingNames = draftModifications
            .filter((modification) => modification.affectsPrice)
            .map((modification) => modification.name);
        const inferredDefaultPrice = batchDraft.price > 0
            ? batchDraft.price
            : Number(Object.entries(pricingRows.reduce<Record<string, number>>((counts, row) => {
                const price = String(row.price);
                counts[price] = (counts[price] ?? 0) + 1;
                return counts;
            }, {})).sort((left, right) => right[1] - left[1])[0]?.[0] ?? 0);
        const draftPrices = Object.fromEntries(pricingRows
            .filter((row) => Number(row.price) !== inferredDefaultPrice)
            .map((row) => [
                createPricingKey(formPricingNames, formPricingNames.map((name) => row.values[name] ??
                    Object.entries(row.values).find(([key]) => key.toLocaleLowerCase() === name.toLocaleLowerCase())?.[1] ?? "")),
                String(row.price),
            ]));
        const unavailableCombinationKeys = batchDraft.availabilityMatrix?.unavailableCombinations.map(
            (combination) => createAvailabilityKey(draftModifications.map((modification) =>
                combination.values[modification.name] ?? "")),
        ) ?? [];
        setForm({
            batchName: batchDraft.batchName,
            name: batchDraft.name,
            description: batchDraft.description,
            price: String(batchDraft.priceMode === CatalogGenerationPriceMode.ByModification
                ? inferredDefaultPrice
                : batchDraft.price),
            categoryId: String(batchDraft.categoryId),
            itemType: batchDraft.itemType,
            initialStockQuantity: String(batchDraft.initialStockQuantity),
            priceMode: batchDraft.priceMode,
        });
        setModifications(draftModifications);
        setFields(customFieldsToRows(batchDraft.fields));
        setFieldsError("");
        setCombinationPrices(draftPrices);
        setFillPrice("");
        setPricingFilters({});
        setPricingPage(1);
        setAvailabilityMatrix(unavailableCombinationKeys.length > 0
            ? {unavailableCombinationKeys}
            : null);
        setAvailabilityPage(1);
        setExistingImageUrl(batchDraft.imageUrl);
        setImageFile(null);
    }, [batchDraft]);

    const itemTypeOptions = useMemo(() => [
        {id: CategoryType.Product, name: t("Product")},
        {id: CategoryType.Service, name: t("Service")},
    ], [t]);
    const priceModeOptions = useMemo(() => [
        {id: CatalogGenerationPriceMode.Single, name: t("One price for all")},
        {id: CatalogGenerationPriceMode.ByModification, name: t("Price by characteristics")},
    ], [t]);

    const currentUnavailableCombinationKeys = useMemo(() => {
        if (!availabilityMatrix) return [];
        const knownValues = modifications.map((modification) =>
            new Set(modification.values.map(({value}) => normalizeAvailabilityValue(value))),
        );

        return availabilityMatrix.unavailableCombinationKeys.filter((key) => {
            try {
                const values = JSON.parse(key) as unknown;
                return Array.isArray(values) &&
                    values.length === modifications.length &&
                    values.every((value, index) => typeof value === "string" && knownValues[index].has(value));
            } catch {
                return false;
            }
        });
    }, [availabilityMatrix, modifications]);

    const rawTotal = useMemo(() => {
        if (!modifications.length || modifications.some((modification) => !modification.values.length)) return 0;
        return modifications.reduce((result, modification) => {
            const next = result * modification.values.length;
            return Number.isSafeInteger(next) ? next : Number.MAX_SAFE_INTEGER;
        }, 1);
    }, [modifications]);

    const total = useMemo(() => {
        return Math.max(0, rawTotal - currentUnavailableCombinationKeys.length);
    }, [currentUnavailableCombinationKeys, rawTotal]);

    const selectedPricingModifications = useMemo(() => modifications
        .map((modification, index) => ({modification, index}))
        .filter(({modification}) => modification.affectsPrice), [modifications]);
    const pricingRows = useMemo(() => {
        if (form.priceMode !== CatalogGenerationPriceMode.ByModification ||
            selectedPricingModifications.length === 0 ||
            rawTotal === 0 ||
            rawTotal > maximumPreviewCombinations) return [];

        const unavailable = new Set(currentUnavailableCombinationKeys);
        const names = selectedPricingModifications.map(({modification}) => modification.name.trim());
        const uniqueRows = new Map<string, {key: string; values: string[]}>();
        for (let index = 0; index < rawTotal; index++) {
            const fullValues = getCombinationValues(modifications, index);
            if (unavailable.has(createAvailabilityKey(fullValues))) continue;
            const values = selectedPricingModifications.map((item) => fullValues[item.index]);
            const key = createPricingKey(names, values);
            if (!uniqueRows.has(key)) uniqueRows.set(key, {key, values});
        }
        return Array.from(uniqueRows.values());
    }, [currentUnavailableCombinationKeys, form.priceMode, modifications, rawTotal, selectedPricingModifications]);
    const filteredPricingRows = useMemo(() => pricingRows.filter((row) =>
        selectedPricingModifications.every(({index}, pricingIndex) => {
            const filter = pricingFilters[index];
            return !filter || normalizeAvailabilityValue(row.values[pricingIndex]) === normalizeAvailabilityValue(filter);
        })), [pricingFilters, pricingRows, selectedPricingModifications]);
    const pricingPageCount = Math.max(1, Math.ceil(filteredPricingRows.length / pricingPageSize));
    const visiblePricingRows = useMemo(() => filteredPricingRows.slice(
        (pricingPage - 1) * pricingPageSize,
        pricingPage * pricingPageSize,
    ), [filteredPricingRows, pricingPage]);
    const overriddenPriceCount = useMemo(() => pricingRows.filter(({key}) =>
        Object.prototype.hasOwnProperty.call(combinationPrices, key)).length,
    [combinationPrices, pricingRows]);

    const availabilityPageCount = Math.max(1, Math.ceil(rawTotal / availabilityPageSize));
    const availabilityRows = useMemo(() => {
        if (!availabilityMatrix || rawTotal === 0) return [];
        const firstIndex = (availabilityPage - 1) * availabilityPageSize;
        const lastIndex = Math.min(rawTotal, firstIndex + availabilityPageSize);
        return Array.from({length: Math.max(0, lastIndex - firstIndex)}, (_, offset) =>
            getCombinationValues(modifications, firstIndex + offset),
        );
    }, [availabilityMatrix, availabilityPage, modifications, rawTotal]);

    useEffect(() => {
        setAvailabilityPage((current) => Math.min(current, availabilityPageCount));
    }, [availabilityPageCount]);

    useEffect(() => {
        setPricingPage((current) => Math.min(current, pricingPageCount));
    }, [pricingPageCount]);

    useEffect(() => {
        setCombinationPrices((current) => {
            const entries = Object.entries(current).filter(([, price]) =>
                !price.trim() || Number(price) !== Number(form.price));
            return entries.length === Object.keys(current).length
                ? current
                : Object.fromEntries(entries);
        });
    }, [form.price]);

    const namePreview = useMemo(() => {
        const parts = modifications
            .filter((modification) => modification.addToName)
            .map((modification) => modification.values[0]?.value.trim())
            .filter(Boolean);
        return [form.name.trim(), ...parts].filter(Boolean).join(" ");
    }, [form.name, modifications]);

    useEffect(() => {
        if (!jobId || isTerminal) return;
        const intervalId = window.setInterval(() => { void statusQuery.refetch(); }, 1500);
        return () => window.clearInterval(intervalId);
    }, [isTerminal, jobId, statusQuery]);

    useEffect(() => {
        if (job?.status !== CatalogGenerationJobStatus.Completed) return;
        dispatch(productsApi.util.invalidateTags(["Products", "Product"]));
        dispatch(servicesApi.util.invalidateTags(["Services", "Service"]));
        dispatch(stockApi.util.invalidateTags(["Stock"]));
    }, [dispatch, job?.status]);

    const updateModification = (index: number, patch: Partial<GenerationModification>) => {
        setModifications((current) => current.map((item, itemIndex) => itemIndex === index ? {...item, ...patch} : item));
    };

    const resetAvailabilityRestrictions = () => {
        setAvailabilityMatrix((current) => current ? {unavailableCombinationKeys: []} : null);
        setAvailabilityPage(1);
        setPricingFilters({});
        setPricingPage(1);
    };

    const removeModification = (index: number) => {
        setModifications((current) => current.filter((_, itemIndex) => itemIndex !== index));
        setAvailabilityMatrix((current) => current && modifications.length > 1
            ? {unavailableCombinationKeys: []}
            : null);
        setAvailabilityPage(1);
        setPricingFilters({});
        setPricingPage(1);
    };

    const toggleAvailability = (values: string[]) => {
        const key = createAvailabilityKey(values);
        setAvailabilityMatrix((current) => {
            if (!current) return null;
            const isUnavailable = current.unavailableCombinationKeys.includes(key);
            return {
                unavailableCombinationKeys: isUnavailable
                    ? current.unavailableCombinationKeys.filter((item) => item !== key)
                    : [...current.unavailableCombinationKeys, key],
            };
        });
    };

    const unavailableCombinationKeySet = useMemo(
        () => new Set(currentUnavailableCombinationKeys),
        [currentUnavailableCombinationKeys],
    );

    const applyFillPrice = () => {
        const price = Number(fillPrice);
        if (!Number.isFinite(price) || price <= 0) return;
        setCombinationPrices((current) => {
            const next = {...current};
            filteredPricingRows.forEach((row) => {
                if (price === Number(form.price)) {
                    delete next[row.key];
                } else {
                    next[row.key] = fillPrice;
                }
            });
            return next;
        });
    };

    const resetPriceOverrides = () => {
        setCombinationPrices({});
        setFillPrice("");
    };

    const updateCombinationPrice = (key: string, value: string) => {
        setCombinationPrices((current) => {
            const next = {...current};
            if (value.trim() && Number(value) === Number(form.price)) {
                delete next[key];
            } else {
                next[key] = value;
            }
            return next;
        });
    };

    const resetCombinationPrice = (key: string) => {
        setCombinationPrices((current) => {
            const next = {...current};
            delete next[key];
            return next;
        });
    };

    const validate = () => {
        if (!form.batchName.trim() || !form.name.trim() || !form.description.trim() || !form.categoryId) {
            setValidationError(t("Fill in all required product or service fields."));
            return false;
        }
        const initialStockQuantity = Number(form.initialStockQuantity);
        if (form.itemType === CategoryType.Product &&
            (!Number.isFinite(initialStockQuantity) || initialStockQuantity < 0)) {
            setValidationError(t("Initial stock quantity cannot be negative."));
            return false;
        }
        if (!Number.isFinite(Number(form.price)) || Number(form.price) <= 0) {
            setValidationError(t("Price must be positive!"));
            return false;
        }
        const customFieldsError = getCustomFieldsValidationError(fields, t);
        setFieldsError(customFieldsError);
        if (customFieldsError) {
            setValidationError(customFieldsError);
            return false;
        }
        if (!modifications.length) {
            setValidationError(t("Add at least one characteristic."));
            return false;
        }

        const names = new Set<string>();
        for (const modification of modifications) {
            const name = modification.name.trim();
            if (!name || !modification.values.length || modification.values.some(({value}) => !value.trim())) {
                setValidationError(t("Characteristic names and values cannot be empty."));
                return false;
            }
            const normalizedName = name.toLocaleLowerCase();
            if (names.has(normalizedName)) {
                setValidationError(t("Characteristic names must be unique."));
                return false;
            }
            names.add(normalizedName);

            const values = modification.values.map(({value}) => value.trim().toLocaleLowerCase());
            if (new Set(values).size !== values.length) {
                setValidationError(t("Values inside one characteristic must be unique."));
                return false;
            }
        }
        if (form.priceMode === CatalogGenerationPriceMode.ByModification) {
            if (selectedPricingModifications.length === 0) {
                setValidationError(t("Select at least one price-forming characteristic."));
                return false;
            }
            if (pricingRows.length === 0 || pricingRows.some(({key}) => {
                const price = Number(Object.prototype.hasOwnProperty.call(combinationPrices, key)
                    ? combinationPrices[key]
                    : form.price);
                return !Number.isFinite(price) || price <= 0;
            })) {
                setValidationError(t("Specify a positive final price for every available price combination."));
                return false;
            }
        }
        setValidationError("");
        return true;
    };

    const submit = async (event: React.FormEvent) => {
        event.preventDefault();
        if (!validate()) return;

        const formData = new FormData();
        formData.append("batchName", form.batchName);
        formData.append("name", form.name);
        formData.append("description", form.description);
        formData.append("price", form.price);
        formData.append("priceMode", String(form.priceMode));
        formData.append("categoryId", form.categoryId);
        formData.append("itemType", String(form.itemType));
        formData.append(
            "initialStockQuantity",
            form.itemType === CategoryType.Product ? form.initialStockQuantity || "0" : "0",
        );
        formData.append("modifications", JSON.stringify(modifications.map((modification) => ({
            name: modification.name,
            values: modification.values.map(({value}) => value),
            addToName: modification.addToName,
            addToDescription: modification.addToDescription,
            valuePrices: [],
        }))));
        formData.append("fields", JSON.stringify(customFieldRowsToRecord(fields)));
        if (form.priceMode === CatalogGenerationPriceMode.ByModification) {
            const modificationNames = selectedPricingModifications.map(({modification}) => modification.name.trim());
            formData.append("pricingJson", JSON.stringify({
                modificationNames,
                combinationPrices: pricingRows.map((row) => ({
                    values: Object.fromEntries(modificationNames.map((name, index) => [name, row.values[index]])),
                    price: Number(Object.prototype.hasOwnProperty.call(combinationPrices, row.key)
                        ? combinationPrices[row.key]
                        : form.price),
                })),
            }));
        }
        if (availabilityMatrix && currentUnavailableCombinationKeys.length > 0) {
            formData.append("availabilityMatrixJson", JSON.stringify({
                unavailableCombinations: currentUnavailableCombinationKeys.map((key) => {
                    const values = JSON.parse(key) as string[];
                    return {
                        values: Object.fromEntries(modifications.map((modification, index) => [
                            modification.name.trim(),
                            values[index],
                        ])),
                    };
                }),
            }));
        }
        if (imageFile) formData.append("imageFile", imageFile);

        try {
            const result = isEditMode
                ? await editGenerationBatch({batchId: editBatchId, formData}).unwrap()
                : await startGeneration(formData).unwrap();
            setJobId(result.jobId);
            toast.success(t(isEditMode ? "Batch update started." : "Generation job started."));
        } catch (error) {
            toast.error(getApiErrorMessage(error, t(isEditMode
                ? "Batch editing could not be started."
                : "Generation could not be started.")));
        }
    };

    const cancel = async () => {
        if (!jobId) return;
        try {
            await cancelGeneration(jobId).unwrap();
            await statusQuery.refetch();
            toast.success(t("Generation job cancelled."));
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Generation could not be cancelled.")));
        }
    };

    const statusLabels: Record<CatalogGenerationJobStatus, string> = {
        [CatalogGenerationJobStatus.Pending]: t("Pending"),
        [CatalogGenerationJobStatus.Running]: t("Running"),
        [CatalogGenerationJobStatus.Completed]: t("Completed"),
        [CatalogGenerationJobStatus.Failed]: t("Failed"),
        [CatalogGenerationJobStatus.Cancelled]: t("Cancelled"),
    };

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t(isEditMode ? "Editing generation batch" : "Generation of products and services")}</PageTitle>
                    <PageSubtitle>{t(isEditMode
                        ? "Catalog items will be safely replaced after the background update completes."
                        : "Create every unique combination of characteristic values in a background job.")}</PageSubtitle>
                </PageTitleGroup>
                <NavLink to="/catalogGeneration/batches" style={{textDecoration: "none"}}>
                    <CoreButton text={t("Generation batches")} leftIcon={<ViewListOutlinedIcon/>}/>
                </NavLink>
            </PageHeader>
            {!isEditMode && <CatalogGenerationTabs/>}
            <FormSurface onSubmit={submit}>
                <CoreTextField fieldArray required value={form.batchName} label={t("Batch name")} onChange={(event: any) => setForm({...form, batchName: event.target.value})}/>
                <CoreFormControl verticalMargin>
                    <InputLabel>{t("Catalog item type")}</InputLabel>
                    <CoreSelect disabled={isEditMode} value={form.itemType} label={t("Catalog item type")} menuItemProps={itemTypeOptions} onChange={(event: any) => {
                        setForm({...form, itemType: Number(event.target.value), categoryId: "", initialStockQuantity: "0"});
                        setExistingImageUrl("");
                    }}/>
                </CoreFormControl>
                <CoreFormControl verticalMargin>
                    <InputLabel>{t("Category")}</InputLabel>
                    <CoreSelect value={form.categoryId} label={t("Category")} menuItemProps={categories} onChange={(event: any) => setForm({...form, categoryId: String(event.target.value)})}/>
                </CoreFormControl>
                <CoreTextField fieldArray value={form.name} label={t("Name")} onChange={(event: any) => setForm({...form, name: event.target.value})}/>
                <CoreTextField fieldArray value={form.description} label={t("Description")} onChange={(event: any) => setForm({...form, description: event.target.value})}/>
                {form.itemType === CategoryType.Product && (
                    <CoreTextField fieldArray type="number" value={form.initialStockQuantity} label={t("Initial stock quantity")} onChange={(event: any) => setForm({...form, initialStockQuantity: event.target.value})}/>
                )}
                <CoreFormControl verticalMargin>
                    <InputLabel>{t("Price mode")}</InputLabel>
                    <CoreSelect value={form.priceMode} label={t("Price mode")} menuItemProps={priceModeOptions} onChange={(event: any) => setForm({...form, priceMode: Number(event.target.value)})}/>
                </CoreFormControl>
                {form.priceMode === CatalogGenerationPriceMode.Single && (
                    <CoreTextField fieldArray type="number" value={form.price} label={t("Price")} onChange={(event: any) => setForm({...form, price: event.target.value})}/>
                )}
                {form.priceMode === CatalogGenerationPriceMode.ByModification && (
                    <AvailabilityPanel>
                        <CoreTextField fieldArray type="number" value={form.price} label={t("Default price")} onChange={(event: any) => setForm({...form, price: event.target.value})}/>
                        <span>{t("The default price is applied automatically. In the matrix below, change only combinations with a different price.")}</span>
                    </AvailabilityPanel>
                )}
                <ImageUploadField label={t("Image")} actionText={t("Choose file")} emptyText={t("No file selected")} hint={t("PNG, JPG or WEBP")} fileName={imageFile?.name} previewSrc={imageFile ? undefined : existingImageUrl} previewAlt={form.name || t("Catalog item")} onChange={(event) => setImageFile(event.target.files?.[0] ?? null)}/>

                <CustomFieldEditor value={fields} onChange={setFields} error={fieldsError}/>

                <Typography variant="h6">{t("Characteristics")}</Typography>
                {modifications.map((modification, modificationIndex) => (
                    <ModificationCard key={modificationIndex}>
                        <ModificationHeader>
                            <CoreTextField fieldArray value={modification.name} label={t("Characteristic name")} onChange={(event: any) => updateModification(modificationIndex, {name: event.target.value})}/>
                            <CoreButton type="button" muiType="error" leftIcon={<DeleteOutlineIcon/>} ariaLabel={t("Remove characteristic")} onClick={() => removeModification(modificationIndex)}/>
                        </ModificationHeader>
                        <ModificationOptions>
                            <FormControlLabel
                                control={<Checkbox checked={modification.addToName} onChange={(event) => updateModification(modificationIndex, {addToName: event.target.checked})}/>}
                                label={t("Add to name")}
                            />
                            <FormControlLabel
                                control={<Checkbox checked={modification.addToDescription} onChange={(event) => updateModification(modificationIndex, {addToDescription: event.target.checked})}/>}
                                label={t("Add to description")}
                            />
                            {form.priceMode === CatalogGenerationPriceMode.ByModification && (
                                <FormControlLabel
                                    control={<Checkbox checked={modification.affectsPrice} onChange={(event) => {
                                        updateModification(modificationIndex, {affectsPrice: event.target.checked});
                                        setPricingFilters({});
                                        setPricingPage(1);
                                    }}/>}
                                    label={t("Price depends on this characteristic")}
                                />
                            )}
                        </ModificationOptions>
                        {modification.values.map((value, valueIndex) => (
                            <ValueRow key={valueIndex}>
                                <ValueFields>
                                    <CoreTextField fieldArray value={value.value} label={t("Value {number}", {number: valueIndex + 1})} onChange={(event: any) => {
                                        updateModification(modificationIndex, {values: modification.values.map((item, index) => index === valueIndex ? {...item, value: event.target.value} : item)});
                                        resetAvailabilityRestrictions();
                                    }}/>
                                </ValueFields>
                                <CoreButton type="button" muiType="error" leftIcon={<DeleteOutlineIcon/>} ariaLabel={t("Remove value")} onClick={() => {
                                    updateModification(modificationIndex, {values: modification.values.filter((_, index) => index !== valueIndex)});
                                    resetAvailabilityRestrictions();
                                }}/>
                            </ValueRow>
                        ))}
                        <CoreButton type="button" muiType="info" leftIcon={<AddCircleOutlineIcon/>} text={t("Add value")} onClick={() => {
                            updateModification(modificationIndex, {values: [...modification.values, {value: "", price: ""}]});
                            resetAvailabilityRestrictions();
                        }}/>
                    </ModificationCard>
                ))}
                <CoreButton type="button" muiType="info" leftIcon={<AddCircleOutlineIcon/>} text={t("Add characteristic")} onClick={() => {
                    setModifications((current) => [...current, {name: "", values: [{value: "", price: ""}], addToName: false, addToDescription: false, affectsPrice: false}]);
                    resetAvailabilityRestrictions();
                }}/>

                <Typography variant="h6">{t("Availability matrix")}</Typography>
                {!availabilityMatrix ? (
                    <AvailabilityPanel>
                        <span>{t("Optional. If the matrix is not configured, every combination is available.")}</span>
                        <CoreButton
                            type="button"
                            muiType="info"
                            disabled={modifications.length === 0 || rawTotal === 0}
                            text={t("Configure availability matrix")}
                            onClick={() => {
                                setAvailabilityMatrix({unavailableCombinationKeys: []});
                                setAvailabilityPage(1);
                            }}
                        />
                    </AvailabilityPanel>
                ) : (
                    <AvailabilityPanel>
                        <span>{t("All combinations are enabled initially. Clear a checkbox to exclude an unavailable combination.")}</span>
                        <MatrixScroller>
                            <MatrixTable>
                                <thead>
                                    <tr>
                                        {modifications.map((modification, modificationIndex) => (
                                            <MatrixHeaderCell key={modificationIndex}>{modification.name.trim() || t("Characteristic {number}", {number: modificationIndex + 1})}</MatrixHeaderCell>
                                        ))}
                                        <MatrixHeaderCell>{t("Available")}</MatrixHeaderCell>
                                    </tr>
                                </thead>
                                <tbody>
                                    {availabilityRows.map((values) => {
                                        const key = createAvailabilityKey(values);
                                        return (
                                            <tr key={key}>
                                                {values.map((value, valueIndex) => (
                                                    <MatrixCell key={valueIndex}>{value}</MatrixCell>
                                                ))}
                                                <MatrixCell>
                                                    <Checkbox
                                                        checked={!unavailableCombinationKeySet.has(key)}
                                                        inputProps={{"aria-label": t("Availability of combination {values}", {values: values.join(" / ")})}}
                                                        onChange={() => toggleAvailability(values)}
                                                    />
                                                </MatrixCell>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </MatrixTable>
                        </MatrixScroller>
                        {availabilityPageCount > 1 && (
                            <MatrixPagination>
                                <Pagination page={availabilityPage} count={availabilityPageCount} onChange={(_, page) => setAvailabilityPage(page)}/>
                            </MatrixPagination>
                        )}
                        <span>{t("Unavailable combinations: {count}", {count: currentUnavailableCombinationKeys.length})}</span>
                        {currentUnavailableCombinationKeys.length > 0 && (
                            <CoreButton type="button" muiType="info" text={t("Enable all combinations")} onClick={resetAvailabilityRestrictions}/>
                        )}
                        <CoreButton type="button" muiType="error" text={t("Disable availability matrix")} onClick={() => {
                            setAvailabilityMatrix(null);
                            setAvailabilityPage(1);
                        }}/>
                    </AvailabilityPanel>
                )}

                {form.priceMode === CatalogGenerationPriceMode.ByModification && (
                    <>
                        <Typography variant="h6">{t("Price matrix")}</Typography>
                        <AvailabilityPanel>
                            <span>{t("Select the characteristics that affect price. Every combination starts with the default price; add only the necessary exceptions.")}</span>
                            {selectedPricingModifications.length === 0 ? (
                                <strong>{t("Select at least one price-forming characteristic.")}</strong>
                            ) : (
                                <>
                                    <strong>{t("Price combinations: {count}; individual prices: {overrides}", {
                                        count: pricingRows.length,
                                        overrides: overriddenPriceCount,
                                    })}</strong>
                                    <PricingFilters>
                                        {selectedPricingModifications.map(({modification, index}) => {
                                            const label = modification.name.trim() || t("Characteristic {number}", {number: index + 1});
                                            return (
                                                <CoreFormControl key={index} verticalMargin>
                                                    <InputLabel>{t("Filter: {name}", {name: label})}</InputLabel>
                                                    <CoreSelect
                                                        required={false}
                                                        value={pricingFilters[index] ?? ""}
                                                        label={t("Filter: {name}", {name: label})}
                                                        menuItemProps={[
                                                            {id: "", name: t("All values")},
                                                            ...modification.values.map(({value}) => ({id: value, name: value})),
                                                        ]}
                                                        onChange={(event: any) => {
                                                            setPricingFilters((current) => ({...current, [index]: event.target.value}));
                                                            setPricingPage(1);
                                                        }}
                                                    />
                                                </CoreFormControl>
                                            );
                                        })}
                                        <CoreButton
                                            type="button"
                                            muiType="info"
                                            disabled={!Object.values(pricingFilters).some(Boolean)}
                                            text={t("Clear price filters")}
                                            onClick={() => {
                                                setPricingFilters({});
                                                setPricingPage(1);
                                            }}
                                        />
                                    </PricingFilters>
                                    <span>{t("Shown price combinations: {shown} of {total}", {
                                        shown: filteredPricingRows.length,
                                        total: pricingRows.length,
                                    })}</span>
                                    <PriceToolbar>
                                        <CoreTextField fieldArray type="number" value={fillPrice} label={t("Price for shown combinations")} onChange={(event: any) => setFillPrice(event.target.value)}/>
                                        <CoreButton type="button" muiType="info" disabled={Number(fillPrice) <= 0 || filteredPricingRows.length === 0} text={t("Apply to shown ({count})", {count: filteredPricingRows.length})} onClick={applyFillPrice}/>
                                    </PriceToolbar>
                                    {overriddenPriceCount > 0 && (
                                        <CoreButton type="button" muiType="info" text={t("Reset all individual prices")} onClick={resetPriceOverrides}/>
                                    )}
                                    <MatrixScroller>
                                        <MatrixTable>
                                            <thead>
                                                <tr>
                                                    {selectedPricingModifications.map(({modification, index}) => (
                                                        <MatrixHeaderCell key={index}>{modification.name.trim() || t("Characteristic {number}", {number: index + 1})}</MatrixHeaderCell>
                                                    ))}
                                                    <MatrixHeaderCell>{t("Final price")}</MatrixHeaderCell>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {visiblePricingRows.map((row) => {
                                                    const changed = Object.prototype.hasOwnProperty.call(combinationPrices, row.key);
                                                    return (
                                                        <tr key={row.key}>
                                                            {row.values.map((value, index) => <MatrixCell key={index}>{value}</MatrixCell>)}
                                                            <MatrixCell>
                                                                <PriceCellContent>
                                                                    <CoreTextField
                                                                        fieldArray
                                                                        type="number"
                                                                        value={changed ? combinationPrices[row.key] : form.price}
                                                                        label={t("Final price")}
                                                                        onChange={(event: any) => updateCombinationPrice(row.key, event.target.value)}
                                                                    />
                                                                    <IconButton
                                                                        disabled={!changed}
                                                                        title={t("Reset to default price")}
                                                                        aria-label={t("Reset to default price")}
                                                                        onClick={() => resetCombinationPrice(row.key)}
                                                                    >
                                                                        <RestartAltOutlinedIcon/>
                                                                    </IconButton>
                                                                    <PriceOrigin changed={changed}>{t(changed ? "Individual price" : "Default price")}</PriceOrigin>
                                                                </PriceCellContent>
                                                            </MatrixCell>
                                                        </tr>
                                                    );
                                                })}
                                            </tbody>
                                        </MatrixTable>
                                    </MatrixScroller>
                                    {pricingPageCount > 1 && (
                                        <MatrixPagination>
                                            <Pagination page={pricingPage} count={pricingPageCount} onChange={(_, page) => setPricingPage(page)}/>
                                        </MatrixPagination>
                                    )}
                                </>
                            )}
                        </AvailabilityPanel>
                    </>
                )}

                <Summary>
                    <strong>{t("Products or services to create: {count}", {count: total})}</strong>
                    <span>{modifications.map((modification) => modification.values.length).join(" × ") || "0"} = {rawTotal}</span>
                    {currentUnavailableCombinationKeys.length > 0 && <span>{t("Available after matrix exclusions: {count}", {count: total})}</span>}
                    {namePreview && <span>{t("Name example: {name}", {name: namePreview})}</span>}
                </Summary>
                {validationError && <ErrorText>{validationError}</ErrorText>}
                <CoreButton type="submit" fullWidth muiType="success" disabled={isSaving || total === 0} text={isSaving
                    ? t("Starting...")
                    : t(isEditMode ? "Save batch changes" : "Start generation")}/>
            </FormSurface>

            {jobId && (
                <JobPanel>
                    <Typography variant="h6">{t("Generation status")}: {job ? statusLabels[job.status] : t("Loading...")}</Typography>
                    <LinearProgress variant="determinate" value={job?.total ? Math.min(100, job.processed / job.total * 100) : 0}/>
                    <strong>{t("Created {created} / {total}", {created: job?.created ?? 0, total: job?.total ?? 0})}</strong>
                    {job && <span>{t("Processed: {processed}; skipped or failed: {failed}", {processed: job.processed, failed: job.failed})}</span>}
                    {job?.error && <ErrorText>{job.error}</ErrorText>}
                    {!isTerminal && <CoreButton type="button" muiType="error" disabled={isCancelling} text={t("Cancel generation")} onClick={() => { void cancel(); }}/>} 
                </JobPanel>
            )}
        </MainDiv>
    );
};

export default CatalogGenerationPage;
