import React from "react";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import styledCom from "styled-components";
import CoreButton from "../../../ui/buttons/coreButton";
import CoreTextField from "../../../ui/textFields/coreTextField";

export interface CharacteristicRow {
    name: string;
    value: string;
}

interface Props {
    title: string;
    description?: string;
    nameLabel: string;
    valueLabel: string;
    addLabel: string;
    removeLabel: string;
    value: CharacteristicRow[];
    onChange: (value: CharacteristicRow[]) => void;
    error?: string;
}

const Editor = styledCom.section({
    display: "grid",
    gap: "12px",
    padding: "16px",
    border: "1px solid var(--color-border)",
    borderRadius: "12px",
    background: "var(--color-surface-soft)",
});

const Heading = styledCom.h2({
    margin: 0,
    color: "var(--color-text)",
    fontSize: "18px",
});

const Description = styledCom.p({
    margin: 0,
    color: "var(--color-muted)",
    fontSize: "13px",
    lineHeight: 1.5,
});

const Row = styledCom.div({
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 1fr) auto",
    gap: "10px",
    alignItems: "center",

    "@media (max-width: 640px)": {
        gridTemplateColumns: "1fr",
    },
});

const ErrorText = styledCom.p({
    margin: 0,
    color: "var(--color-danger)",
    fontSize: "13px",
    fontWeight: 650,
});

const CharacteristicEditor = ({
    title,
    description,
    nameLabel,
    valueLabel,
    addLabel,
    removeLabel,
    value,
    onChange,
    error,
}: Props) => {
    const update = (index: number, field: keyof CharacteristicRow, fieldValue: string) => {
        onChange(value.map((row, rowIndex) =>
            rowIndex === index ? {...row, [field]: fieldValue} : row,
        ));
    };

    return (
        <Editor>
            <Heading>{title}</Heading>
            {description && <Description>{description}</Description>}
            {value.map((row, index) => (
                <Row key={index}>
                    <CoreTextField
                        fieldArray
                        value={row.name}
                        label={nameLabel}
                        onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                            update(index, "name", event.target.value)}
                    />
                    <CoreTextField
                        fieldArray
                        value={row.value}
                        label={valueLabel}
                        onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                            update(index, "value", event.target.value)}
                    />
                    <CoreButton
                        type="button"
                        muiType="error"
                        leftIcon={<DeleteOutlineIcon/>}
                        ariaLabel={removeLabel}
                        onClick={() => onChange(value.filter((_, rowIndex) => rowIndex !== index))}
                    />
                </Row>
            ))}
            {error && <ErrorText>{error}</ErrorText>}
            <CoreButton
                type="button"
                muiType="info"
                leftIcon={<AddCircleOutlineIcon/>}
                text={addLabel}
                onClick={() => onChange([...value, {name: "", value: ""}])}
            />
        </Editor>
    );
};

export default CharacteristicEditor;
