import React from "react";
import {Translate, useTranslation} from "../../../i18n";
import CharacteristicEditor, {CharacteristicRow} from "../characteristics/CharacteristicEditor";

export type CustomFieldRow = CharacteristicRow;

interface Props {
    value: CustomFieldRow[];
    onChange: (value: CustomFieldRow[]) => void;
    error?: string;
}

export const customFieldsToRows = (
    fields?: Record<string, string> | null,
): CustomFieldRow[] => Object.entries(fields ?? {}).map(([name, value]) => ({name, value}));

export const customFieldRowsToRecord = (
    rows: CustomFieldRow[],
): Record<string, string> => Object.fromEntries(
    rows.map(({name, value}) => [name.trim(), value.trim()]),
);

export const getCustomFieldsValidationError = (
    rows: CustomFieldRow[],
    t: Translate,
): string => {
    const names = new Set<string>();

    for (const row of rows) {
        const name = row.name.trim();
        const value = row.value.trim();

        if (!name || !value) {
            return t("Field name and value are required.");
        }
        if (name.length > 100) {
            return t("Field name cannot exceed 100 characters.");
        }
        if (value.length > 250) {
            return t("Field value cannot exceed 250 characters.");
        }

        const normalizedName = name.toLocaleLowerCase();
        if (names.has(normalizedName)) {
            return t("Field names must be unique.");
        }
        names.add(normalizedName);
    }

    return "";
};

const CustomFieldEditor = ({value, onChange, error}: Props) => {
    const {t} = useTranslation();

    return (
        <CharacteristicEditor
            title={t("Custom fields")}
            description={t("For example: GTIN, vendor code or another value that does not create a modification.")}
            nameLabel={t("Field name")}
            valueLabel={t("Value")}
            addLabel={t("Add field")}
            removeLabel={t("Remove field")}
            value={value}
            onChange={onChange}
            error={error}
        />
    );
};

export default CustomFieldEditor;
